<x-layouts.app :title="$invoice->number">
<div class="page-head"><div><p class="eyebrow">{{ ucfirst($invoice->type) }} invoice</p><h1>{{ $invoice->number }}</h1><p>Created from <a href="{{ route('quotations.show',$invoice->quotation) }}">{{ $invoice->quotation->number }}</a> for {{ $invoice->customer->name }}.</p></div><a class="button secondary" href="{{ route('invoices.index') }}">Back to invoices</a></div>
<article class="quote-preview"><header><div><strong>{{ $activeWorkspace->legal_name ?: $activeWorkspace->name }}</strong><p>{{ $activeWorkspace->email }}</p></div><div><span class="record-status {{ $invoice->status===\App\Enums\InvoiceStatus::Paid?'active':'inactive' }}">{{ ucfirst($invoice->status->value) }}</span><p>Due {{ $invoice->due_date->format('M j, Y') }}</p></div></header><div class="preview-columns"><div><p class="eyebrow">Bill to</p><h2>{{ $invoice->customer->name }}</h2><p>{{ $invoice->customer->email }}</p></div><div><p>Issued {{ $invoice->issue_date->format('M j, Y') }}</p><p>{{ strtoupper($invoice->currency) }}</p></div></div><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td><strong>{{ $item->name }}</strong><small>{{ $item->description }}</small></td><td>{{ rtrim(rtrim($item->quantity,'0'),'.') }} {{ $item->unit }}</td><td>{{ $invoice->currency }} {{ number_format($item->unit_price_minor/100,2) }}</td><td>{{ $invoice->currency }} {{ number_format($item->total_minor/100,2) }}</td></tr>@endforeach</tbody></table><div class="totals"><div><span>Subtotal</span><strong>{{ $invoice->currency }} {{ number_format($invoice->subtotal_minor/100,2) }}</strong></div><div><span>Tax</span><strong>{{ $invoice->currency }} {{ number_format($invoice->tax_minor/100,2) }}</strong></div><div class="grand"><span>Total</span><strong>{{ $invoice->currency }} {{ number_format($invoice->total_minor/100,2) }}</strong></div><div><span>Paid</span><strong>{{ $invoice->currency }} {{ number_format($invoice->paid_minor/100,2) }}</strong></div><div><span>Balance</span><strong>{{ $invoice->currency }} {{ number_format($invoice->balance_minor/100,2) }}</strong></div></div>@if($invoice->payment_instructions)<section class="public-copy"><h2>Payment instructions</h2><p>{{ $invoice->payment_instructions }}</p></section>@endif</article>
<section class="detail-grid finance-grid">@if($invoice->balance_minor>0 && auth()->user()->canInWorkspace($activeWorkspace,'payments.manage'))<article class="panel"><h2>Collect payment</h2><p class="muted">Provider returns never mark an invoice paid. Only a verified webhook can confirm an online payment.</p>@if(config('payments.stripe.enabled') || config('payments.paypal.enabled'))<div class="provider-actions">@if(config('payments.stripe.enabled'))<form method="POST" action="{{ route('invoices.checkout',$invoice) }}">@csrf<input type="hidden" name="provider" value="stripe"><button class="button secondary">Pay with Stripe</button></form>@endif @if(config('payments.paypal.enabled'))<form method="POST" action="{{ route('invoices.checkout',$invoice) }}">@csrf<input type="hidden" name="provider" value="paypal"><button class="button secondary">Pay with PayPal</button></form>@endif</div>@else<div class="alert">Online providers are disabled until credentials and webhook IDs are configured.</div>@endif<hr><h2>Record manual payment</h2><form class="form-stack" method="POST" action="{{ route('invoices.payments.manual',$invoice) }}">@csrf<label>Amount ({{ $invoice->currency }})<input name="amount" inputmode="decimal" value="{{ number_format($invoice->balance_minor/100,2,'.','') }}" required></label><label>Payment reference<input name="reference" placeholder="Bank reference or receipt number" required></label><label>Paid date<input type="date" name="paid_at" value="{{ now()->toDateString() }}" required></label><button class="button primary">Record confirmed payment</button></form></article>@endif<article class="panel"><div class="panel-head"><div><h2>Payment history</h2><p>Provider and manual records used for the current balance.</p></div>@if(auth()->user()->canInWorkspace($activeWorkspace,'payments.manage'))<form method="POST" action="{{ route('invoices.reconcile',$invoice) }}">@csrf<button class="button secondary">Reconcile</button></form>@endif</div>@forelse($invoice->payments as $payment)<div class="payment-row"><div><strong>{{ $invoice->currency }} {{ number_format($payment->amount_minor/100,2) }}</strong><small>{{ ucfirst($payment->provider) }} · {{ $payment->reference ?: $payment->provider_payment_id }}</small></div><div><span class="record-status {{ $payment->status===\App\Enums\PaymentStatus::Succeeded?'active':'inactive' }}">{{ ucfirst($payment->status->value) }}</span><small>{{ $payment->paid_at?->format('M j, Y') }}</small></div><div>@if($payment->receipt)<strong>{{ $payment->receipt->number }}</strong><small>Receipt issued</small>@else<small>No receipt</small>@endif</div></div>@empty<div class="empty-state compact"><p>No payments recorded.</p></div>@endforelse</article></section>
